window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-48087c8f0083efac"]={"versions": [{"id": "FIG-48087c8f0083efac", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Virtual Function Bus (VFB) Spezifikation zur formalen Modellierung von Timing- und Traceability-Konzepten. Das Modell definiert die fundamentale metarelationale Struktur zwischen einem generischen Ereignisbegriff und seinen zeitlich diskreten Ausprägungen zur Beobachtung oder Messung des Systemverhaltens.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Entitäten über eine gerichtete oder benannte Assoziation:</p>\n<ul class=\"fig-list\"><li><strong><code>Event</code></strong>: Kursiv gesetzte (abstrakte) Klasse als Basistyp für Ereignisse im Systemkontext. Besitzt die Rollenbezeichnung <code>+event</code> mit der Multiplizität <code>1</code>.\n</li><li><strong><code>EventOccurrence</code></strong>: Konkrete Klasse zur Erfassung einer individuellen Instanz/Ausprägung eines Ereignisses. Sie enthält das öffentliche Attribut <code>+ occurrenceTime: TimePoint</code>. Auf ihrer Assoziationsseite trägt sie die Rollenbezeichnung <code>+occurrences</code> mit der Multiplizität <code>*</code> (0..*).\n</li></ul>\n<p class=\"fig-p\">Die Assoziation verknüpft genau ein <code>Event</code> mit beliebig vielen (<code>*</code>) <code>EventOccurrence</code>-Objekten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Strukturdefinition. Ein <code>Event</code> fungiert als zeitunabhängige Spezifikations- oder Auslöser-Definition. Zur Laufzeit oder während einer Trace-Analyse wird bei jedem Eintreffen dieses Ereignisses ein <code>EventOccurrence</code>-Objekt erzeugt oder referenziert, dessen Zeitpunkt über <code>occurrenceTime</code> mit dem Datentyp <code>TimePoint</code> fixiert ist. Die 1-zu-n-Beziehung erlaubt die historische Nachverfolgung aller aufgetretenen Vorkommnisse eines spezifischen Events über die Zeitachse.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Metamodelle und Trace-Formate im AUTOSAR VFB- und Timing-Umfeld:</p>\n<ul class=\"fig-list\"><li>Jede Instanz von <code>EventOccurrence</code> muss zwingend exakt einem <code>Event</code> zugeordnet sein (<code>1</code>).\n</li><li>Ein <code>Event</code> kann existieren, ohne dass bisher eine Ausprägung stattgefunden hat (Multiplizität <code>*</code> umfasst <code>0</code>).\n</li><li>Der Zeitstempel <code>occurrenceTime</code> muss vom Typ <code>TimePoint</code> sein. Entwickler und Tool-Hersteller müssen sicherstellen, dass die zeitliche Auflösung und das Format von <code>TimePoint</code> den Anforderungen an Traceability und Latenzanalysen entsprechen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7cb7ee9a594e7e1b", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR Virtual Function Bus (VFB) Spezifikation zur formalen Modellierung von Timing- und Traceability-Konzepten. Das Modell definiert die fundamentale metarelationale Struktur zwischen einem generischen Ereignisbegriff und seinen zeitlich diskreten Ausprägungen zur Beobachtung oder Messung des Systemverhaltens.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert zwei Entitäten über eine gerichtete oder benannte Assoziation:</p>\n<ul class=\"fig-list\"><li><strong><code>Event</code></strong>: Kursiv gesetzte (abstrakte) Klasse als Basistyp für Ereignisse im Systemkontext. Besitzt die Rollenbezeichnung <code>+event</code> mit der Multiplizität <code>1</code>.\n</li><li><strong><code>EventOccurrence</code></strong>: Konkrete Klasse zur Erfassung einer individuellen Instanz/Ausprägung eines Ereignisses. Sie enthält das öffentliche Attribut <code>+ occurrenceTime: TimePoint</code>. Auf ihrer Assoziationsseite trägt sie die Rollenbezeichnung <code>+occurrences</code> mit der Multiplizität <code>*</code> (0..*).\n</li></ul>\n<p class=\"fig-p\">Die Assoziation verknüpft genau ein <code>Event</code> mit beliebig vielen (<code>*</code>) <code>EventOccurrence</code>-Objekten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Strukturdefinition. Ein <code>Event</code> fungiert als zeitunabhängige Spezifikations- oder Auslöser-Definition. Zur Laufzeit oder während einer Trace-Analyse wird bei jedem Eintreffen dieses Ereignisses ein <code>EventOccurrence</code>-Objekt erzeugt oder referenziert, dessen Zeitpunkt über <code>occurrenceTime</code> mit dem Datentyp <code>TimePoint</code> fixiert ist. Die 1-zu-n-Beziehung erlaubt die historische Nachverfolgung aller aufgetretenen Vorkommnisse eines spezifischen Events über die Zeitachse.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindend für Metamodelle und Trace-Formate im AUTOSAR VFB- und Timing-Umfeld:</p>\n<ul class=\"fig-list\"><li>Jede Instanz von <code>EventOccurrence</code> muss zwingend exakt einem <code>Event</code> zugeordnet sein (<code>1</code>).\n</li><li>Ein <code>Event</code> kann existieren, ohne dass bisher eine Ausprägung stattgefunden hat (Multiplizität <code>*</code> umfasst <code>0</code>).\n</li><li>Der Zeitstempel <code>occurrenceTime</code> muss vom Typ <code>TimePoint</code> sein. Entwickler und Tool-Hersteller müssen sicherstellen, dass die zeitliche Auflösung und das Format von <code>TimePoint</code> den Anforderungen an Traceability und Latenzanalysen entsprechen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-48087c8f0083efac", "to": "FIG-7cb7ee9a594e7e1b", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
